import axios from 'axios';

const axiosInstance = axios.create({
  baseURL: 'http://localhost:5000/api',
  withCredentials: true, // Для отправки cookies
});

// Перехватчик запросов: добавление токена в заголовки
axiosInstance.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Перехватчик ответов: обновление токена при истечении access-токена
axiosInstance.interceptors.response.use(
  (response) => response, // Возврат ответа, если всё успешно
  async (error) => {
    const originalRequest = error.config;

    // Проверка на ошибку 403 (токен истёк) и что запрос не был повторён ранее
    if (error.response?.status === 403 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        // Запрос на обновление access-токена
        const { data } = await axios.post(
          'http://localhost:5000/api/auth/refresh-token',
          {},
          { withCredentials: true } // Передача cookies с refresh-токеном
        );

        // Сохранение нового access-токена в локальном хранилище
        localStorage.setItem('token', data.accessToken);

        // Добавление нового токена в заголовок оригинального запроса
        originalRequest.headers['Authorization'] = `Bearer ${data.accessToken}`;

        // Повторный запрос с новым токеном
        return axiosInstance(originalRequest);
      } catch (refreshError) {
        console.error('Ошибка при обновлении токена:', refreshError);

        // Очистка данных и перенаправление на страницу входа
        localStorage.clear();
        window.location.href = '/';
      }
    }

    return Promise.reject(error);
  }
);

export default axiosInstance;
